def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 2:
                centers.append((r, c))
    # Join aligned diamond centers with color 1, leaving each diamond's 2-cell tips intact.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i+1:]:
            if r1 == r2 and abs(c2-c1) >= 4:
                lo, hi = sorted((c1, c2))
                for c in range(lo + 2, hi - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and abs(r2-r1) >= 4:
                lo, hi = sorted((r1, r2))
                for r in range(lo + 2, hi - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out
